describe('Mail Template Log Business Logic', function (): void {
    it('can create mail template log with basic information', function (): void {
        /** @var \Illuminate\Database\Eloquent\Collection */
        $template = MailTemplate/** @phpstan-ignore-line */ ::factory()->create();

        $logData = [
            'template_id' => $template->id,
            'mailable_type' => 'App\Mail\AppointmentConfirmation',
            'mailable_id' => 123,
            'status' => 'sent',
            'status_message' => 'Email inviata con successo',
            'data' => [
                'recipient' => 'patient@example.com',
                'subject' => 'Conferma Appuntamento',
                'variables' => [
                    'patient_name' => 'Mario Rossi',
                    'appointment_date' => '2024-12-15 10:00:00',
                ],
            ],
            'metadata' => [
                'ip_address' => '192.168.1.100',
                'user_agent' => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
                'campaign_id' => 'appointment_confirmation_001',
            ],
            'sent_at' => now(),
        ];

        $log = MailTemplateLog::create($logData);

        /** @phpstan-ignore-next-line property.notFound */
        $this->assertDatabaseHas('mail_template_logs', [
            'id' => $log->id,
            'template_id' => $template->id,
            'mailable_type' => 'App\Mail\AppointmentConfirmation',
            'mailable_id' => 123,
            'status' => 'sent',
            'status_message' => 'Email inviata con successo',
        ]);

