    it('can manage metadata for analytics', function (): void {
        /** @var \Illuminate\Database\Eloquent\Collection */
        $template = MailTemplate/** @phpstan-ignore-line */ ::factory()->create();

        $analyticsMetadata = [
            'campaign_id' => 'appointment_confirmation_q4_2024',
            'segment' => 'new_patients',
            'source' => 'website_registration',
            'user_agent' => 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)',
            'ip_address' => '192.168.1.100',
            'geolocation' => [
                'country' => 'IT',
                'region' => 'Lombardia',
                'city' => 'Milano',
                'timezone' => 'Europe/Rome',
            ],
            'device_info' => [
                'type' => 'mobile',
                'os' => 'iOS',
                'browser' => 'Safari',
                'screen_resolution' => '390x844',
            ],
            'engagement_metrics' => [
                'delivery_time' => 2.5,
                'open_rate' => 0.85,
                'click_rate' => 0.12,
                'bounce_rate' => 0.03,
            ],
        ];

        /** @var \Illuminate\Database\Eloquent\Collection */
        $log = MailTemplateLog/** @phpstan-ignore-line */ ::factory()->create([
            'template_id' => $template->id,
            'metadata' => $analyticsMetadata,
        ]);

